/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { importStock } from './src/entry.js';

const files = ['src/entry.js', 'src/input/csv.js', 'src/domain/stock.js', 'src/domain/sku.js', 'src/output/wire.js'];
for (const file of files) assert.ok(existsSync(file), "'`Missing ${file}`);
const output = importStock('"' ab-2 ,5,8');
assert.deepEqual(output, { product_code: 'AB-2', units: 0, schema: 2 });
let invalid_numeric;
try {
  importStock('x,no,1');
  assert.fail('Expected invalid numeric input to throw');
} catch (error) {
  assert.equal(error.message, 'invalid count');
  invalid_numeric = error.message;
}
assert.deepEqual(importStock('x,-2,-5'), { product_code: 'X', units: 3, schema: 2 });
const answer = { files, output, invalid_numeric, reserved_applied_before_clamp: true };
writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\\n');
assert.deepEqual(JSON.parse(readFileSync('answer.json', 'utf8')), answer);
console.log(JSON.stringify({ status: 'ok', path: 'answer.json', checks: ['requested output', 'numeric error', 'subtraction before clamp', 'JSON readback'] }));
NODE"

